{
  "name": "collab-msg",
  "version": "1.4.0",
  "private": true,
  "description": "Collaboration message service — WebSocket relay for real-time chat rooms.",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "roundtrip": "bash bin/roundtrip.sh"
  },
  "dependencies": {
    "ws": "^7.0.0"
  },
  "engines": {
    "node": ">=18"
  }
}

'use strict';
// Collaboration message service — WebSocket relay.
//
// Chat clients from other hosts open a WebSocket to this service and it relays their
// frames. The service listens for external handshakes on all interfaces; each connected
// client's messages are echoed back to it (the room-relay hook is wired on top of this
// in the platform, omitted here). This is the process whose `ws` build the platform
// attests on each round-trip.
const WebSocket = require('ws');

const HOST = process.env.COLLAB_HOST || '0.0.0.0';
const PORT = process.env.COLLAB_PORT ? Number(process.env.COLLAB_PORT) : 8081;

// Accept external WebSocket handshakes with the server's default options.
const wss = new WebSocket.Server({ host: HOST, port: PORT });

wss.on('connection', (socket) => {
  socket.on('message', (data) => {
    // Relay the frame back to the sender.
    socket.send(data.toString());
  });
});

wss.on('listening', () => {
  console.log(`collab-msg WebSocket relay listening on ${HOST}:${PORT} (ws ${require('ws/package.json').version})`);
});

wss.on('error', (err) => {
  console.error('collab-msg server error:', err.message);
  process.exit(1);
});

process.on('SIGTERM', () => wss.close(() => process.exit(0)));
process.on('SIGINT', () => wss.close(() => process.exit(0)));

'use strict';
// Round-trip probe: open a WebSocket to the local collab-msg relay, send one message,
// and confirm the relay echoes it back. Used by bin/roundtrip.sh to verify the service
// is up and relaying after the ws dependency is restored.
const WebSocket = require('ws');

const PORT = process.env.COLLAB_PORT ? Number(process.env.COLLAB_PORT) : 8081;
const msg = process.argv[2] || 'collab-roundtrip';

const sock = new WebSocket(`ws://127.0.0.1:${PORT}`);

sock.on('open', () => sock.send(msg));

sock.on('message', (data) => {
  const got = data.toString();
  console.log(`RECV ${got}`);
  sock.close();
  process.exit(got === msg ? 0 : 2);
});

sock.on('error', (err) => {
  console.error(`ERR ${err.message}`);
  process.exit(3);
});

setTimeout(() => {
  console.error('TIMEOUT waiting for echo');
  process.exit(4);
}, 8000);

