{"command":"cd /testbed/collab-msg && PORT=9199 COLLAB_PORT=9199 node server.js &
sleep 1
# Send several messages in sequence
node -e "
const WebSocket = require('/testbed/collab-msg/node_modules/ws');
const sock = new WebSocket('ws://127.0.0.1:9199');
const msgs = ['ping', 'hello world', 'test-123', 'final'];
let idx = 0;
sock.on('open', () => sock.send(msgs[idx]));
sock.on('message', (data) => {
  const got = data.toString();
  console.log('ECHO:', got, got === msgs[idx] ? 'OK' : 'MISMATCH');
  idx++;
  if (idx < msgs.length) sock.send(msgs[idx]);
  else { sock.close(); process.exit(0); }
});
sock.on('error', (e) => { console.error(e); process.exit(1); });
setTimeout(() => { console.error('TIMEOUT'); process.exit(2); }, 5000);
